const MONTHS=['Mar-26','Apr-26','May-26','Jun-26','Jul-26','Aug-26'];
function plTable(st){
  const monthly=st>=1,fac=st>=2,pct=st>=3;
  const cols=v=>monthly?[v.a[0],v.a[1],...v.m,v.a[2]]:v.a;
  const rev=cols(PL_ROWS[0]);
  const cell=(x,i)=>pct?(x/rev[i]*100).toFixed(1)+'%':fmt(x);
  const head=['FY 2024','FY 2025',...(monthly?MONTHS:[]),'TTM Aug-26'];
  let h=`<table class="tbl"><thead><tr><th>Account</th>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>`;
  for(const r of PL_ROWS){
    const caret=r.car?`<span class="car${r.fac?' fac-caret':''}">${r.fac&&fac?'▼':'▶'}</span>`:'<span class="car"></span>';
    h+=`<tr class="${r.c||''}"><td>${caret}${r.n}</td>${cols(r).map((x,i)=>`<td class="${monthly&&i>1&&i<8?'m':''}">${cell(x,i)}</td>`).join('')}</tr>`;
    if(r.kids&&fac)for(const k of r.kids){const kv=monthly?[k[1][0],k[1][1],...k[2],k[1][2]]:k[1];h+=`<tr class="kid"><td>${k[0]}</td>${kv.map((x,i)=>`<td>${cell(x,i)}</td>`).join('')}</tr>`}
  }
  return h+'</tbody></table>';
}
