/* ---------- instantiate apps ---------- */
function stFlow(S,P){
  const src=(S||['P&L','GL','Balance sheet','Other financials']).map((n,i)=>[n,120+i*80]);
  const steps=(P||['Categorize','Adjust','Review','Report']).map((n,i)=>[n,470+i*140]);
  const jx=360,jy=240;
  let s='';
  src.forEach(([n,y],i)=>{s+=`<path d="M150 ${y} C 260 ${y}, 280 ${jy}, ${jx} ${jy}" class="ln"/><g transform="translate(96,${y-17})" class="doc"><rect width="44" height="34" rx="6"/><path d="M11 12h18M11 18h22M11 24h14"/></g><text x="80" y="${y+6}" text-anchor="end" class="sl">${n}</text><circle r="3.5" class="pk" opacity="0"><set attributeName="opacity" to="1" begin="${i*1.6}s"/><animateMotion dur="7.5s" begin="${i*1.6}s" repeatCount="indefinite" path="M150 ${y} C 260 ${y}, 280 ${jy}, ${jx} ${jy} L 890 ${jy}"/></circle>`});
  s+=`<path d="M${jx} ${jy} L 860 ${jy}" class="ln tr"/>`;
  steps.forEach(([n,x],i)=>{const last=i===3;s+=`<g class="stp2${last?' fin':''}" style="animation-delay:${1.4+i*1.4}s"><rect x="${x-30}" y="${jy-26}" width="60" height="52" rx="12"/><path d="M${x-14} ${jy-9}h28M${x-14} ${jy}h${last?28:20}M${x-14} ${jy+9}h28"/></g><text x="${x}" y="${jy+56}" text-anchor="middle" class="sl">${n}</text>`});
  return s;
}
function coverWin(kind){
  const head=n=>`<div class="cvw-top"><b class="cvw-name">${n}</b></div>`;
  if(kind==='cover-sos'){
    const N=[['Intake','#041E40','#fff','<path d="M-7-10h9l5 5v15H-7z"/><path d="M2-10v5h5M-3 1h7M-3 5h7"/>'],['Scrape','#0F75BC','#fff','<circle cx="-2" cy="-2" r="7"/><path d="m3 3 6 6"/>'],['Transformation','#5B8FD6','#fff','<path d="M-9-6h12M-9 0h18M-9 6h8"/><path d="m5 3 4 3-4 3"/>'],['Intelligence','#383B6E','#fff','<path d="M0 10s-7-6-7-11a7 7 0 0 1 14 0c0 5-7 11-7 11Z"/><circle cx="0" cy="-1" r="2.4"/>'],['Tiering','#7A7FB8','#fff','<path d="M-8 8V2M-3 8V-3M3 8V-7M8 8V-10"/>'],['Enrich','#BACAEC','#041E40','<path d="M-1-9-6 1h5l-1 8 7-11H0l1-7z"/>'],['Outreach','#FFFFFF','#041E40','<path d="M-9-6h18v12H-9z"/><path d="m-9-6 9 7 9-7"/>']];
    const cx=520,cy=330,r=140,C=2*Math.PI*r,head0=180/C*360;
    const nodes=N.map((n,i)=>{const th=-90+i*360/N.length,a=th*Math.PI/180,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r,lx=cx+Math.cos(a)*(r+54),ly=cy+Math.sin(a)*(r+54)+6;
      const t=((((th-head0)%360)+360)%360)/360*14,dl=(((t-1.4)%14)+14)%14,anc=Math.abs(Math.cos(a))<.2?'middle':Math.cos(a)>0?'start':'end';
      return `<g class="cvn" style="--c:${n[1]};animation-delay:${dl.toFixed(2)}s"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="34" fill="${n[1]}" opacity=".14"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="25" fill="${n[1]}" stroke="rgba(255,255,255,.5)" stroke-width="1.2"/><g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})" fill="none" stroke="${n[2]}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${n[3]}</g></g><text class="sl" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anc}">${n[0]}</text>`}).join('');
    return `<div class="win cvw cvw-sos cvw-v4"><div class="cvw-in"><svg class="cvw-art" viewBox="0 0 1040 620" preserveAspectRatio="xMidYMid slice">
      <defs><linearGradient id="cmt" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#8cc8ff" stop-opacity="0"/><stop offset="1" stop-color="#8cc8ff"/></linearGradient></defs>
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="rgba(255,255,255,.14)"/>
      <g class="orbit" style="transform-origin:${cx}px ${cy}px"><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="url(#cmt)" stroke-width="2.4" opacity=".8" stroke-linecap="round" stroke-dasharray="180 2000"/></g>${nodes}</svg>${head('Sourcing OS','Build, enrich and <em>monitor.</em>')}</div></div>`}
  return `<div class="win cvw cvw-st cvw-v4"><div class="cvw-in"><svg class="cvw-art" viewBox="0 0 1040 620" preserveAspectRatio="xMidYMid slice"><g transform="translate(124 127) scale(.88)">${stFlow()}</g></svg>${head('Strata','From raw GL to <em>final report.</em>')}</div></div>`;
}
$$('[data-stflow]').length&&$$('[data-stflow]').forEach(el=>{el.innerHTML=`<svg class="st-flow-svg" viewBox="-40 92 980 290" aria-hidden="true">${stFlow()}</svg>`});
