/* ---------- people ---------- */

/* =====================================================================
   Scene engine: progress is eased toward the scroll position every frame
   ===================================================================== */
const scenes=[];
function scene(el,fn){if(el)scenes.push({el,fn,c:-1,last:-1,top:0})}
let running=false;
function layoutScenes(){scenes.forEach(s=>{const sk=$('.sticky',s.el);s.top=sk?parseFloat(getComputedStyle(sk).top)||0:0;s.c=-1;s.last=-1})}
function frame(){
  running=false;let again=false;const vh=innerHeight;
  for(const s of scenes){
    if(s.el.closest('.view').hidden)continue;
    const r=s.el.getBoundingClientRect();
    const total=Math.max(1,r.height-(vh-s.top));
    const t=clamp((s.top-r.top)/total);
    if(s.c<0||RM)s.c=t;else{s.c+=(t-s.c)*.14;if(Math.abs(t-s.c)<.0003)s.c=t;else again=true}
    if(Math.abs(s.c-s.last)>.00003){s.last=s.c;s.fn(s.c,s.el,r)}
  }
  chapters();reveals();
  if(again)req();
}
function req(){if(!running){running=true;requestAnimationFrame(frame)}}
addEventListener('scroll',req,{passive:true});
let rz;addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(()=>{fitAll();heroLayout();layoutScenes();sizeMap();req()},120)});

/* Jump to a section: fade out, move instantly, snap every scene to its new position, fade in */
function jumpTo(y){
  const near=Math.abs(y-scrollY)<innerHeight*1.2;
  if(near||RM){window.scrollTo({top:y,behavior:RM?'auto':'smooth'});return}
  const m=document.querySelector('main');m.classList.add('jumping');
  setTimeout(()=>{window.scrollTo({top:y,behavior:'instant'});scenes.forEach(s=>{s.c=-1});frame();requestAnimationFrame(()=>m.classList.remove('jumping'))},200);
}
/* ---------- Hero ---------- */
const H={start:400,end:80};
function heroLayout(){
  const st=$('#heroSticky'),copy=$('#heroCopy'),btns=$('#heroBtns'),rig=$('#heroRig');if(!st.clientHeight)return;
  const bottom=copy.offsetTop+btns.offsetTop+btns.offsetHeight;
  H.start=st.clientHeight+60;H.end=Math.max(14,(st.clientHeight-rig.offsetHeight)/2);
}
scene($('[data-scene="hero"]'),p=>{
  const copy=$('#heroCopy'),rig=$('#heroRig');
  const f=seg(p,0,.18);
  copy.style.opacity=1-f;copy.style.visibility=f>=1?'hidden':'visible';
  copy.style.transform=`translateY(${-eo(seg(p,0,.26))*90}px)`;
  const a=ease(seg(p,.04,.62));if(a>.55)rig.classList.add('go');rig.style.opacity=Math.min(1,seg(p,.02,.3)*1.4);
  if(a>=.999){rig.style.transform=`translate(-50%,${Math.round(H.end)}px)`;rig.classList.add('settled')}else{rig.classList.remove('settled');rig.style.transform=`translate(-50%,${lerp(H.start,H.end,a)}px) rotateX(${lerp(26,0,a)}deg) scale(${lerp(.88,1,a)})`}
  const cap=seg(p,.42,.6);$$('.hero-cap',rig).forEach(c=>{c.style.opacity=cap;c.style.transform=`translateY(${(1-cap)*12}px)`});
});

/* ---------- Word reveal ---------- */
$$('[data-words]').forEach(el=>{
  const em=(el.dataset.em||'').split(',');
  el.innerHTML=el.dataset.words.split(' ').map(w=>`<span class="${em.includes(w.replace(/\W/g,''))?'em':''}">${w}</span>`).join(' ');
  const spans=$$('span',el);
  scene(el.closest('.scene'),p=>{const k=seg(p,.05,.78)*spans.length;spans.forEach((s,i)=>s.style.opacity=RM?1:clamp(.16+(k-i)*.84,.16,1))});
});

/* ---------- Lifecycle ---------- */
scene($('[data-scene="life"]'),p=>{
  const st=$$('.stage'),n=Math.max(1,Math.floor(seg(p,.06,.84)*st.length+.001));
  st.forEach((s,i)=>s.classList.toggle('on',i<n));
  $('#lifeFill').style.width=(clamp((n-1)/(st.length-1))*100)+'%';
  $('#loopNote').classList.toggle('on',p>.88);
});

/* ---------- Chapters ---------- */
function chapters(){
  const mid=innerHeight*(innerWidth<900?.72:.5);
  $$('[data-chapter]').forEach(ch=>{
    if(ch.closest('.view').hidden)return;
    const beats=$$('.beat',ch);let best=beats[0],bd=1e9;
    beats.forEach(b=>{const r=b.getBoundingClientRect();const d=Math.abs((r.top+r.bottom)/2-mid);if(d<bd){bd=d;best=b}});
    if(ch._best===best)return;ch._best=best;
    beats.forEach(b=>b.classList.toggle('on',b===best));
    const w=$('[data-chapter-app] .win',ch);if(!w)return;
    setShot(w,best.dataset.st,{show:true});
  });
}

/* ---------- Reveals ---------- */
