$$('[data-tour]').forEach(sc=>{
  const T=TOURS[sc.dataset.tour],fit=$('.tour-fit',sc),win=T.make();fit.appendChild(win);
  const groups=[...new Set(T.steps.map(s=>s[1]))];
  $('.tour-list',sc).innerHTML=groups.map(g=>`<li><b>${g}</b><p></p></li>`).join('');
  const st={idx:-1};sc._tour=st;
  const set=i=>{if(i===st.idx)return;st.idx=i;const s=T.steps[i],g=groups.indexOf(s[1]);T.set(win,s[0]);
    $$('.tour-list li',sc).forEach((li,k)=>{const was=li.classList.contains('on');li.classList.toggle('on',k===g);if(k===g){const p=$('p',li);clearTimeout(li._t);if(was&&p.textContent&&p.textContent!==s[2]&&!RM){p.classList.add('fade');li._t=setTimeout(()=>{p.textContent=s[2];p.classList.remove('fade')},220)}else{p.textContent=s[2];p.classList.remove('fade')}}});
    $('.tour-count',sc).textContent=`${String(i+1).padStart(2,'0')} / ${String(T.steps.length).padStart(2,'0')}`;
    {const mc=$('.tour-mcap',sc),put=()=>{$('b',mc).textContent=s[1];$('p',mc).textContent=s[2];mc.classList.remove('fade')};clearTimeout(sc._mcT);if(!$('p',mc).textContent||RM)put();else{mc.classList.add('fade');sc._mcT=setTimeout(put,250)}}
    sc.dispatchEvent(new CustomEvent('tourstep',{detail:{i,key:s[0],group:g}}));};
  sc._tourJump=k=>{k=(T.alias&&T.alias[k])||k;const i=T.steps.findIndex(s=>s[1]===k||s[0]===k);if(i<0)return;const r=sc.getBoundingClientRect(),sk=$('.sticky',sc);const top=parseFloat(getComputedStyle(sk).top)||0;const total=r.height-(innerHeight-top);const p=.05+(i+.5)/T.steps.length*(.985-.05);jumpTo(r.top+scrollY-top+total*p)};
  scene(sc,p=>{const a=eo(seg(p,0,.05));fit.style.transform=`rotateX(${lerp(22,0,a)}deg) scale(${lerp(.9,1,a)}) translateY(${lerp(40,0,a)}px)`;set(Math.min(T.steps.length-1,Math.floor(seg(p,.05,.985)*T.steps.length)))});
});

