/* ---------- Routing (path based) ---------- */
const VIEWS=['technology','strata','sourcing-os'];
const TITLES={technology:'Technology | STOC Advisory',strata:'Strata | STOC Advisory','sourcing-os':'Sourcing OS | STOC Advisory'};
const hdrH=()=>{const v=parseFloat(getComputedStyle(ROOT).getPropertyValue('--hdr'));return isNaN(v)?72:v};
const viewFromPath=()=>{const p=location.pathname.replace(/\/+$/,'');const rest=p.startsWith(TECH_BASE)?p.slice(TECH_BASE.length).replace(/^\//,''):'';return VIEWS.includes(rest)?rest:'technology'};
const pathFor=v=>v==='technology'?TECH_BASE:TECH_BASE+'/'+v;
function route(){
  const v=viewFromPath();
  $$('.view').forEach(x=>x.hidden=x.dataset.view!==v);
  document.title=TITLES[v]||document.title;
  window.scrollTo(0,0);
  $$('[data-tour]').forEach(t=>{if(t._tour)t._tour.idx=-1});lastStep=-1;
  $$('[data-chapter]').forEach(c=>c._best=null);
  if(typeof lb!=='undefined'&&!lb.hidden){lb.hidden=true;document.documentElement.style.overflow=''}
  document.dispatchEvent(new CustomEvent('stoc:viewchange',{detail:{view:v}}));
  requestAnimationFrame(()=>{if(afterRoute){const id=afterRoute;afterRoute=null;setTimeout(()=>{const t=document.getElementById(id);if(t)window.scrollTo({top:t.getBoundingClientRect().top+scrollY-hdrH()-52,behavior:'instant'});scenes.forEach(s=>s.c=-1);frame()},60)}fitAll();heroLayout();if(v==='sourcing-os'){initMap();sizeMap()}layoutScenes();initReveals();req()});
}
addEventListener('popstate',route);
